// Some portions generated by Claude
package org.eclipse.rdf4j.queryrender;

import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertAll;

import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.query.MalformedQueryException;
import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.QueryParseOptions;
import org.eclipse.rdf4j.query.algebra.AggregateFunctionCall;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor;
import org.eclipse.rdf4j.query.parser.ParsedQuery;
import org.eclipse.rdf4j.query.parser.QueryParserUtil;
import org.eclipse.rdf4j.queryrender.sparql.SPARQLQueryRenderer;
import org.eclipse.rdf4j.queryrender.sparql.TupleExprIRRenderer;
import org.eclipse.rdf4j.queryrender.sparql.TupleExprIRRenderer.Config;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.function.Executable;

/**
 * Both query renderers must render the GH-6193 custom aggregates ({@link AggregateFunctionCall}, namespace
 * {@code http://rdf4j.org/aggregate#}) as SPARQL that re-parses to the same aggregate calls: same IRI, same
 * {@code DISTINCT} flag and the same number of arguments, whether the input used prefixed names or full IRIs, and
 * whether the aggregate stands alone in the projection, is nested in an expression or appears in {@code HAVING}.
 */
class CustomAggregateRenderingTest {

	private static final String NAMESPACE = "http://rdf4j.org/aggregate#";

	private static final String PREFIXES = "PREFIX agg: <" + NAMESPACE + ">\n";

	private static final String VALUES = " WHERE { VALUES (?x ?s) { (4 \"ab,c\") (9 \"xyz\") (9 \"xyz\") } }";

	@Test
	void unaryAggregate() {
		assertBothRenderersRoundTrip("SELECT (agg:median(?x) AS ?r)" + VALUES);
	}

	@Test
	void nAryAggregate() {
		assertBothRenderersRoundTrip("SELECT (agg:percentileCont(?x, 0.5) AS ?r)" + VALUES);
	}

	@Test
	void distinctAggregate() {
		assertBothRenderersRoundTrip("SELECT (agg:arrayAgg(DISTINCT ?x) AS ?r)" + VALUES);
	}

	@Test
	void aggregateNestedInProjectionExpression() {
		assertBothRenderersRoundTrip("SELECT (agg:median(?x) * 2 AS ?r)" + VALUES);
	}

	@Test
	void aggregateInHaving() {
		assertBothRenderersRoundTrip("SELECT ?s (agg:median(?x) AS ?r)" + VALUES
				+ " GROUP BY ?s HAVING (agg:percentileCont(?x, 0.9) > 1)");
	}

	@Test
	void groupedAggregatesWithStandardAggregate() {
		assertBothRenderersRoundTrip("SELECT ?s (agg:arrayAgg(DISTINCT ?x) AS ?r) (SUM(?x) AS ?total)" + VALUES
				+ " GROUP BY ?s");
	}

	/** Renders the prefixed and the full-IRI form of the query with both renderers and checks every round trip. */
	private static void assertBothRenderersRoundTrip(String prefixedQuery) {
		String iriQuery = prefixedQuery.replaceAll("\\bagg:([A-Za-z]+)", "<" + NAMESPACE + "$1>");
		assertThat(iriQuery).as("IRI form differs from the prefixed form").isNotEqualTo(prefixedQuery);
		List<Executable> cases = new ArrayList<>();
		for (String query : List.of(prefixedQuery, iriQuery)) {
			for (boolean legacy : List.of(false, true)) {
				cases.add(() -> assertRoundTrip(query, legacy));
			}
		}
		assertAll(cases);
	}

	private static void assertRoundTrip(String query, boolean legacy) throws Exception {
		ParsedQuery original = QueryParserUtil.parseQuery(QueryLanguage.SPARQL, PREFIXES + query, null);
		List<String> expected = aggregateCalls(original.getTupleExpr());
		assertThat(expected).as("the query must contain a custom aggregate").isNotEmpty();

		String rendered = render(original, legacy);
		String context = (legacy ? "legacy" : "IR") + " renderer\n" + query + "\n" + rendered;

		ParsedQuery reparsed;
		try {
			reparsed = QueryParserUtil.parseQuery(QueryLanguage.SPARQL, rendered, null);
		} catch (MalformedQueryException e) {
			throw new AssertionError(context + "\nrendered query does not parse: " + e.getMessage(), e);
		}
		assertThat(aggregateCalls(reparsed.getTupleExpr())).as(context + "\naggregate calls").isEqualTo(expected);

		for (String call : expected) {
			String iri = call.substring(0, call.indexOf(' '));
			assertThat(rendered).as(context + "\naggregate IRI in angle brackets").contains("<" + iri + ">(");
			if (call.contains(" distinct=true ")) {
				assertThat(rendered).as(context + "\nDISTINCT inside the parentheses")
						.contains("<" + iri + ">(DISTINCT ");
			}
		}
	}

	/** Sorted multiset of {@code "<iri> distinct=<flag> args=<count>"} for every custom aggregate call. */
	private static List<String> aggregateCalls(TupleExpr expression) {
		List<String> calls = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(AggregateFunctionCall node) {
				calls.add(node.getIRI() + " distinct=" + node.isDistinct() + " args=" + node.getArguments().size());
				super.meet(node);
			}
		});
		calls.sort(null);
		return calls;
	}

	private static String render(ParsedQuery query, boolean legacy) throws Exception {
		if (legacy) {
			return new SPARQLQueryRenderer().render(query, QueryParseOptions.DEFAULT);
		}
		Config config = new Config();
		config.parseOptions = QueryParseOptions.DEFAULT;
		return new TupleExprIRRenderer(config).render(query.getTupleExpr(), null);
	}
}
